"use strict";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { ErrorCallout } from "components/ErrorCallout";
import { LiquidityModalDetailRows } from "components/Liquidity/LiquidityModalDetailRows";
import { LiquidityPositionInfo } from "components/Liquidity/LiquidityPositionInfo";
import { StyledPercentInput } from "components/PercentInput";
import {
  DecreaseLiquidityStep,
  useRemoveLiquidityModalContext
} from "components/RemoveLiquidity/RemoveLiquidityModalContext";
import { useRemoveLiquidityTxContext } from "components/RemoveLiquidity/RemoveLiquidityTxContext";
import { canUnwrapCurrency } from "pages/Pool/Positions/create/utils";
import { ClickablePill } from "pages/Swap/Buy/PredefinedAmount";
import { NumericalInputMimic, NumericalInputSymbolContainer, NumericalInputWrapper } from "pages/Swap/common/shared";
import { useMemo } from "react";
import { Trans, useTranslation } from "react-i18next";
import { Button, Flex, Switch, Text, useSporeColors } from "ui/src";
import { nativeOnChain } from "uniswap/src/constants/tokens";
import useResizeObserver from "use-resize-observer";
const isValidPercentageInput = (value) => {
  const numValue = Number(value);
  return !isNaN(numValue) && numValue <= 100;
};
export function RemoveLiquidityForm() {
  const hiddenObserver = useResizeObserver();
  const { t } = useTranslation();
  const colors = useSporeColors();
  const { percent, positionInfo, setPercent, setStep, percentInvalid, unwrapNativeCurrency, setUnwrapNativeCurrency } = useRemoveLiquidityModalContext();
  const { gasFeeEstimateUSD, txContext, error, refetch } = useRemoveLiquidityTxContext();
  if (!positionInfo) {
    throw new Error("RemoveLiquidityModal must have an initial state when opening");
  }
  const hasGauge = !!positionInfo.gaugeAddress;
  const walletCurrency0Amount = useMemo(() => {
    if (positionInfo.version === ProtocolVersion.V2 && positionInfo.unstakedAmount && positionInfo.liquidityAmount?.quotient) {
      try {
        const totalLp = positionInfo.liquidityAmount.quotient;
        if (totalLp.toString() === "0") {
          return positionInfo.currency0Amount;
        }
        return positionInfo.currency0Amount.multiply(positionInfo.unstakedAmount).divide(totalLp);
      } catch (error2) {
        console.error("Error calculating wallet currency0 amount:", error2);
        return positionInfo.currency0Amount;
      }
    }
    return positionInfo.currency0Amount;
  }, [positionInfo]);
  const walletCurrency1Amount = useMemo(() => {
    if (positionInfo.version === ProtocolVersion.V2 && positionInfo.unstakedAmount && positionInfo.liquidityAmount?.quotient) {
      try {
        const totalLp = positionInfo.liquidityAmount.quotient;
        if (totalLp.toString() === "0") {
          return positionInfo.currency1Amount;
        }
        return positionInfo.currency1Amount.multiply(positionInfo.unstakedAmount).divide(totalLp);
      } catch (error2) {
        console.error("Error calculating wallet currency1 amount:", error2);
        return positionInfo.currency1Amount;
      }
    }
    return positionInfo.currency1Amount;
  }, [positionInfo]);
  const { currency0Amount, currency1Amount } = positionInfo;
  const canUnwrap0 = canUnwrapCurrency(currency0Amount.currency, positionInfo.version);
  const canUnwrap1 = canUnwrapCurrency(currency1Amount.currency, positionInfo.version);
  const nativeCurrency = nativeOnChain(positionInfo.chainId);
  const canUnwrap = canUnwrap0 || canUnwrap1;
  const unwrapUnderCard = useMemo(() => {
    if (!canUnwrap) {
      return null;
    }
    return <Flex
      row
      backgroundColor="$surface2"
      borderBottomLeftRadius="$rounded12"
      borderBottomRightRadius="$rounded12"
      justifyContent="space-between"
      alignItems="center"
      py="$padding8"
      px="$padding16"
    >
        <Text variant="body3" color="$neutral2">
          <Trans i18nKey="pool.withdrawAs" values={{ nativeWrappedSymbol: nativeCurrency.symbol }} />
        </Text>
        <Switch
      id="add-as-weth"
      checked={unwrapNativeCurrency}
      onCheckedChange={() => setUnwrapNativeCurrency((unwrapNativeCurrency2) => !unwrapNativeCurrency2)}
      variant="branded"
    />
      </Flex>;
  }, [canUnwrap, nativeCurrency, unwrapNativeCurrency, setUnwrapNativeCurrency]);
  return <Flex gap="$gap24">
      {
    /* Position info */
  }
      <Flex width="100%" row justifyContent="space-between" alignItems="center">
        <LiquidityPositionInfo positionInfo={positionInfo} hasGauge={hasGauge} />
      </Flex>
      {
    /* Percent input panel */
  }
      <Flex gap="$gap4">
        <Flex
    backgroundColor="$surface2"
    borderTopLeftRadius="$rounded12"
    borderTopRightRadius="$rounded12"
    borderBottomLeftRadius={canUnwrap ? "$rounded0" : "$rounded12"}
    borderBottomRightRadius={canUnwrap ? "$rounded0" : "$rounded12"}
    p="$padding16"
    gap="$gap12"
  >
          <Text variant="body3" color="$neutral2">
            <Trans i18nKey="common.withdrawal.amount" />
          </Text>
          <Flex row alignItems="center" justifyContent="center" width="100%">
            <NumericalInputWrapper width="100%">
              <StyledPercentInput
    value={percent}
    onUserInput={(value) => {
      if (isValidPercentageInput(value)) {
        setPercent(value);
      }
    }}
    placeholder="0"
    $width={percent && hiddenObserver.width ? hiddenObserver.width + 1 : void 0}
    maxDecimals={0}
    maxLength={3}
  />
              <NumericalInputSymbolContainer showPlaceholder={!percent}>%</NumericalInputSymbolContainer>
              <NumericalInputMimic ref={hiddenObserver.ref}>{percent}</NumericalInputMimic>
            </NumericalInputWrapper>
          </Flex>
          <Flex row gap="$gap8" width="100%" justifyContent="center">
            {[25, 50, 75, 100].map((option) => {
    const active = percent === option.toString();
    const disabled = false;
    return <ClickablePill
      key={option}
      onPress={() => {
        setPercent(option.toString());
      }}
      $disabled={disabled}
      $active={active}
      customBorderColor={colors.surface3.val}
      foregroundColor={colors[disabled ? "neutral3" : active ? "neutral1" : "neutral2"].val}
      label={option < 100 ? option + "%" : t("swap.button.max")}
      px="$spacing16"
      textVariant="buttonLabel2"
    />;
  })}
          </Flex>
        </Flex>
        {unwrapUnderCard}
      </Flex>
      {
    /* Detail rows */
  }
      <LiquidityModalDetailRows
    currency0Amount={walletCurrency0Amount}
    currency1Amount={walletCurrency1Amount}
    networkCost={gasFeeEstimateUSD}
  />
      <ErrorCallout errorMessage={error} onPress={refetch} />
      <Flex row>
        <Button
    isDisabled={percentInvalid || !txContext?.txRequest}
    onPress={() => setStep(DecreaseLiquidityStep.Review)}
    loading={!error && !percentInvalid && !txContext?.txRequest}
    variant="branded"
    key="LoaderButton-animation-RemoveLiquidity-continue"
    size="large"
  >
          {t("common.button.remove")}
        </Button>
      </Flex>
    </Flex>;
}
